      serviceQuality: newReview.serviceQuality,
      privateRoomDetail: newReview.privateRoomDetail,
      bookingEase: 3,
      priceRange: newReview.priceRange,
      hasNomihodai: false,
      comment: newReview.comment,
      createdAt: new Date().toISOString().split('T')[0],
      photos: {
        meal: mealPhotos,
        ambiance: ambiancePhotos,
      },
    };

    setReviews([review, ...reviews]);
    setShowReviewForm(false);
    // Reset form
    setMealPhotos([]);
    setAmbiancePhotos([]);
    setNewReview({
      rating: 5,
      serviceQuality: 5,
      privateRoomDetail: '',
      comment: '',
      priceRange: '¥10,000 - ¥15,000',
