                  ))
                )}
              </div>
            </div>
          </div>

          {/* Sidebar Info */}
          <div className="lg:w-1/3">
            <div className="sticky top-28 space-y-8">
              {/* Action Box */}
              <div className="bg-white p-8 rounded-2xl border border-slate-200 shadow-xl">
                <div className="text-2xl font-bold text-slate-900 mb-2">{restaurant.priceRange}</div>
                <p className="text-sm text-slate-500 mb-8">※表示価格は口コミに基づく参考価格です</p>
