import React, { useEffect, useState, useRef } from 'react';
import { mockRestaurants, mockReviews } from '../data/mockData';
import { analyzeRestaurantForBusiness } from '../services/geminiService';
import { BusinessAnalysis, Restaurant, Review } from '../types';

interface DetailProps {
  id: string;
  onNavigate: (path: string, params?: any) => void;
}

const Detail: React.FC<DetailProps> = ({ id, onNavigate }) => {
  const [restaurant, setRestaurant] = useState<Restaurant | null>(null);
  const [reviews, setReviews] = useState<Review[]>([]);
  const [analysis, setAnalysis] = useState<BusinessAnalysis | null>(null);
  const [isAnalyzing, setIsAnalyzing] = useState(false);
  const [showReviewForm, setShowReviewForm] = useState(false);

  // Form State
  const [newReview, setNewReview] = useState({
    rating: 5,
    serviceQuality: 5,
    privateRoomDetail: '',
    comment: '',
    priceRange: '¥10,000 - ¥15,000',
  });
  const [mealPhotos, setMealPhotos] = useState<string[]>([]);
  const [ambiancePhotos, setAmbiancePhotos] = useState<string[]>([]);

  const mealInputRef = useRef<HTMLInputElement>(null);
  const ambianceInputRef = useRef<HTMLInputElement>(null);

  useEffect(() => {
    const res = mockRestaurants.find(r => r.id === id);
    if (res) {
      setRestaurant(res);
      const resReviews = mockReviews.filter(rv => rv.restaurantId === id);
      setReviews(resReviews);
    }
  }, [id]);

  const handleRunAnalysis = async () => {
    if (!restaurant) return;
    setIsAnalyzing(true);
    const result = await analyzeRestaurantForBusiness(restaurant.name, reviews);
    setAnalysis(result);
    setIsAnalyzing(false);
  };

  // Fixed the iteration logic for FileList to resolve TypeScript error on line 64.
  // Using a standard for loop instead of Array.from to ensure better type inference for File objects.
  const handleFileChange = (e: React.ChangeEvent<HTMLInputElement>, type: 'meal' | 'ambiance') => {
    const files = e.target.files;
    if (!files) return;

    for (let i = 0; i < files.length; i++) {
      const file = files[i];
      if (!file) continue;

      const reader = new FileReader();
      reader.onloadend = () => {
        const base64 = reader.result as string;
        if (type === 'meal') {
          setMealPhotos(prev => [...prev, base64]);
        } else {
          setAmbiancePhotos(prev => [...prev, base64]);
        }
      };
      reader.readAsDataURL(file);
    }
  };

  const handleSubmitReview = (e: React.FormEvent) => {
    e.preventDefault();
    const review: Review = {
      id: `rev-${Date.now()}`,
      restaurantId: id,
      userName: 'ゲスト ユーザー',
      userTitle: 'ビジネスエグゼクティブ',
      rating: newReview.rating,
      serviceQuality: newReview.serviceQuality,
      privateRoomDetail: newReview.privateRoomDetail,
      bookingEase: 3,
      priceRange: newReview.priceRange,
      hasNomihodai: false,
      comment: newReview.comment,
      createdAt: new Date().toISOString().split('T')[0],
      photos: {
        meal: mealPhotos,
        ambiance: ambiancePhotos,
      },
    };

    setReviews([review, ...reviews]);
    setShowReviewForm(false);
    // Reset form
    setMealPhotos([]);
    setAmbiancePhotos([]);
    setNewReview({
      rating: 5,
      serviceQuality: 5,
      privateRoomDetail: '',
      comment: '',
      priceRange: '¥10,000 - ¥15,000',
    });
  };

  if (!restaurant) return <div className="p-20 text-center">Loading...</div>;

  return (
    <div className="animate-in fade-in duration-500 pb-20">
      {/* Photo Gallery Header */}
      <div className="h-[400px] flex overflow-hidden">
        <div className="w-2/3 h-full relative group overflow-hidden">
          <img src={restaurant.image} className="w-full h-full object-cover transition-transform duration-1000 group-hover:scale-105" alt={restaurant.name} />
        </div>
        <div className="w-1/3 flex flex-col">
          <div className="h-1/2 overflow-hidden border-l border-b border-white">
            <img src="https://picsum.photos/id/42/800/600" className="w-full h-full object-cover" />
          </div>
          <div className="h-1/2 overflow-hidden border-l border-white">
            <img src="https://picsum.photos/id/43/800/600" className="w-full h-full object-cover" />
          </div>
        </div>
      </div>

      <div className="max-w-7xl mx-auto px-4 sm:px-6 lg:px-8 py-12">
        <div className="flex flex-col lg:flex-row gap-12">
          {/* Main Info */}
          <div className="lg:w-2/3">
            <div className="mb-8">
              <div className="flex items-center space-x-3 mb-4">
                <span className="bg-slate-900 text-white px-3 py-1 rounded text-xs font-bold">{restaurant.genre}</span>
                <span className="text-slate-500 text-sm">{restaurant.area}</span>
              </div>
              <h1 className="text-4xl font-serif font-bold text-slate-900 mb-6">{restaurant.name}</h1>
              <p className="text-lg text-slate-600 leading-relaxed mb-8">
                {restaurant.description}
              </p>

              {/* Business Specs Grid */}
              <div className="grid grid-cols-2 md:grid-cols-4 gap-4 bg-white p-6 rounded-2xl border border-slate-200 shadow-sm mb-12">
                <div className="text-center p-4 border-r border-slate-100 last:border-0">
                  <span className="block text-slate-400 text-xs uppercase font-bold mb-1">接客の質</span>
                  <div className="flex justify-center text-yellow-500">
                    {[...Array(5)].map((_, i) => (
                      <i key={i} className={`fas fa-star ${i < restaurant.serviceQuality ? '' : 'text-slate-200'}`}></i>
                    ))}
                  </div>
                </div>
                <div className="text-center p-4 border-r border-slate-100 last:border-0">
                  <span className="block text-slate-400 text-xs uppercase font-bold mb-1">予約難易度</span>
                  <div className="text-slate-900 font-bold">
                    {restaurant.bookingEase >= 4 ? '取りやすい' : restaurant.bookingEase >= 2 ? '普通' : '困難'}
                  </div>
                </div>
                <div className="text-center p-4 border-r border-slate-100 last:border-0">
                  <span className="block text-slate-400 text-xs uppercase font-bold mb-1">個室</span>
                  <div className="text-slate-900 font-bold">{restaurant.hasPrivateRoom ? '完全個室あり' : 'なし'}</div>
                </div>
                <div className="text-center p-4 last:border-0">
                  <span className="block text-slate-400 text-xs uppercase font-bold mb-1">飲み放題</span>
                  <div className="text-slate-900 font-bold">{restaurant.hasNomihodai ? 'あり' : 'なし'}</div>
                </div>
              </div>

              {/* AI Analysis Section */}
              <div className="bg-slate-900 rounded-3xl p-8 text-white mb-12 shadow-2xl relative overflow-hidden">
                <div className="absolute top-0 right-0 p-8 opacity-10">
                  <i className="fas fa-brain text-8xl"></i>
                </div>
                <div className="relative z-10">
                  <div className="flex items-center mb-6">
                    <i className="fas fa-sparkles text-yellow-400 mr-2"></i>
                    <h3 className="text-xl font-bold">AIビジネス・コンシェルジュ診断</h3>
                  </div>

                  {!analysis ? (
                    <div className="text-center py-6">
                      <p className="text-slate-400 mb-6">過去の口コミデータをAIが分析し、ビジネス利用の適性を診断します。</p>
                      <button 
                        onClick={handleRunAnalysis}
                        disabled={isAnalyzing}
                        className="bg-white text-slate-900 px-8 py-3 rounded-full font-bold hover:bg-slate-100 transition-all flex items-center mx-auto"
                      >
                        {isAnalyzing ? (
                          <>
                            <i className="fas fa-spinner fa-spin mr-2"></i> 分析中...
                          </>
                        ) : (
                          <>
                            <i className="fas fa-magic mr-2 text-indigo-500"></i> 分析を実行
                          </>
                        )}
                      </button>
                    </div>
                  ) : (
                    <div className="space-y-6">
                      <div className="flex items-end space-x-4">
                        <div className="text-5xl font-serif text-yellow-400">{analysis.suitabilityScore}</div>
                        <div className="text-slate-400 text-sm pb-1 uppercase tracking-widest">Business Suitability Score</div>
                      </div>
                      <p className="text-slate-200 leading-relaxed italic border-l-2 border-slate-700 pl-4">
                        "{analysis.reasoning}"
                      </p>
                      <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
                        <div>
                          <h4 className="text-sm font-bold text-slate-400 mb-3 uppercase tracking-wider">メリット</h4>
                          <ul className="space-y-2">
                            {analysis.pros.map((p, i) => <li key={i} className="flex items-start text-sm"><i className="fas fa-check-circle text-emerald-400 mr-2 mt-1"></i> {p}</li>)}
                          </ul>
                        </div>
                        <div>
                          <h4 className="text-sm font-bold text-slate-400 mb-3 uppercase tracking-wider">最適利用シーン</h4>
                          <div className="flex flex-wrap gap-2">
                            {analysis.bestUseCases.map((u, i) => <span key={i} className="bg-slate-800 text-slate-300 px-3 py-1 rounded-full text-xs">{u}</span>)}
                          </div>
                        </div>
                      </div>
                    </div>
                  )}
                </div>
              </div>

