export const getNearbyInfo = async (restaurantName: string, address: string): Promise<NearbyInfo | null> => {
  if (!process.env.API_KEY) return null;

  // Use Google Maps grounding to find nearby parking and stations
  const prompt = `${restaurantName}（住所: ${address}）の近くにある、接待に利用しやすい駐車場や最寄り駅の出口、タクシー乗り場などの情報を教えてください。ビジネスマンに役立つ情報に絞ってください。`;

  try {
    const response = await ai.models.generateContent({
      model: "gemini-2.5-flash",
      contents: prompt,
      config: {
        tools: [{ googleMaps: {} }],
      },
    });

    const links = response.candidates?.[0]?.groundingMetadata?.groundingChunks
      ?.filter((chunk: any) => chunk.maps)
      ?.map((chunk: any) => ({
        title: chunk.maps.title,
        uri: chunk.maps.uri
      })) || [];

    return {
      text: response.text || "",
      links: links
    };
  } catch (error) {
    console.error("Gemini Maps Error:", error);
    return null;
  }
};

