              <label className="flex items-center space-x-3 cursor-pointer p-4 bg-slate-50 rounded-xl hover:bg-slate-100 transition-all">
                <input type="checkbox" checked={formData.hasPrivateRoom} onChange={e => setFormData({ ...formData, hasPrivateRoom: e.target.checked })} className="w-5 h-5 rounded text-slate-900 focus:ring-slate-900" />
                <span className="text-sm font-bold text-slate-700">完全個室あり</span>
              </label>
              <label className="flex items-center space-x-3 cursor-pointer p-4 bg-slate-50 rounded-xl hover:bg-slate-100 transition-all">
