                <span className="text-sm font-bold text-slate-700">コース料理あり</span>
              </label>
            </div>
            <div className="col-span-2">
              <label className="block text-[10px] font-bold text-slate-500 uppercase mb-2">店舗説明 (エグゼクティブ向けのアピールポイント)</label>
              <textarea rows={4} value={formData.description} onChange={e => setFormData({ ...formData, description: e.target.value })} className="w-full bg-slate-50 border border-slate-100 rounded-2xl px-4 py-4 text-sm focus:ring-2 focus:ring-slate-900 focus:outline-none resize-none" placeholder="お店の雰囲気や接待での強みを詳しく入力してください" required />
