          </div>
        </div>

        <div className="pt-10">
          <button type="submit" className="w-full bg-slate-900 text-white py-5 rounded-2xl font-bold text-lg hover:bg-slate-800 transition-all shadow-2xl">店舗情報を公開する</button>
        </div>
      </form>
    </div>
  );
};

export default Admin;

import React, { useEffect, useState, useRef } from 'react';
import { mockRestaurants, mockReviews } from '../data/mockData';
import { analyzeRestaurantForBusiness, getNearbyInfo } from '../services/geminiService';
import { BusinessAnalysis, Restaurant, Review, NearbyInfo } from '../types';

interface DetailProps {
  id: string;
  onNavigate: (path: string, params?: any) => void;
  allRestaurants: Restaurant[];
}

const Detail: React.FC<DetailProps> = ({ id, onNavigate, allRestaurants }) => {
  const [restaurant, setRestaurant] = useState<Restaurant | null>(null);
  const [reviews, setReviews] = useState<Review[]>([]);
  const [analysis, setAnalysis] = useState<BusinessAnalysis | null>(null);
  const [nearbyInfo, setNearbyInfo] = useState<NearbyInfo | null>(null);
  const [isAnalyzing, setIsAnalyzing] = useState(false);
  const [isGettingNearby, setIsGettingNearby] = useState(false);
  const [showReviewForm, setShowReviewForm] = useState(false);

  const [form, setForm] = useState({
    rating: 5,
    tasteRating: 5,
    serviceQuality: 5,
    quietness: 5,
    hasPrivateRoom: true,
    privateRoomDetail: '',
    priceSpent: '',
    hasCourse: true,
    comment: ''
  });

  const mealInputRef = useRef<HTMLInputElement>(null);
  const ambianceInputRef = useRef<HTMLInputElement>(null);

  useEffect(() => {
    const res = allRestaurants.find(r => r.id === id);
    if (res) {
      setRestaurant(res);
      const resReviews = mockReviews.filter(rv => rv.restaurantId === id);
      setReviews(resReviews);
    }
  }, [id, allRestaurants]);

  const handleRunAnalysis = async () => {
    if (!restaurant) return;
    setIsAnalyzing(true);
    const result = await analyzeRestaurantForBusiness(restaurant.name, reviews);
    setAnalysis(result);
    setIsAnalyzing(false);
  };

  const handleGetNearbyInfo = async () => {
    if (!restaurant) return;
    setIsGettingNearby(true);
    const result = await getNearbyInfo(restaurant.name, restaurant.address);
    setNearbyInfo(result);
    setIsGettingNearby(false);
  };

  const handleSubmitReview = (e: React.FormEvent) => {
    e.preventDefault();
    // Fix: Removed 'bookingEase' and 'hasNomihodai' which are not defined in the Review type.
    const newRev: Review = {
      ...form,
      id: `rev-${Date.now()}`,
      restaurantId: id,
      userName: 'ゲストエグゼクティブ',
      userTitle: '会社役員',
      createdAt: new Date().toISOString().split('T')[0],
    };
    setReviews([newRev, ...reviews]);
    setShowReviewForm(false);
    alert('口コミを投稿しました。貴重な情報をありがとうございます。');
  };

  if (!restaurant) return <div className="p-20 text-center">Loading...</div>;

  const RatingStars = ({ val, label }: { val: number; label: string }) => (
    <div className="flex items-center justify-between">
      <span className="text-xs font-bold text-slate-500">{label}</span>
      <div className="flex text-yellow-400 text-xs">
        {[...Array(5)].map((_, i) => <i key={i} className={`fas fa-star ${i < val ? '' : 'text-slate-200'}`}></i>)}
      </div>
    </div>
  );

  return (
    <div className="animate-in fade-in duration-500 pb-20">
      {/* Photo Gallery Header */}
      <div className="h-[400px] flex overflow-hidden">
        <div className="w-2/3 h-full relative group overflow-hidden">
          <img src={restaurant.image} className="w-full h-full object-cover transition-transform duration-1000 group-hover:scale-105" alt={restaurant.name} />
        </div>
        <div className="w-1/3 flex flex-col">
          <div className="h-1/2 overflow-hidden border-l border-b border-white">
            <img src="https://picsum.photos/id/42/800/600" className="w-full h-full object-cover" />
          </div>
          <div className="h-1/2 overflow-hidden border-l border-white">
            <img src="https://picsum.photos/id/43/800/600" className="w-full h-full object-cover" />
          </div>
        </div>
      </div>

      <div className="max-w-7xl mx-auto px-4 sm:px-6 lg:px-8 py-12">
        <div className="flex flex-col lg:flex-row gap-12">
          {/* Main Info */}
          <div className="lg:w-2/3">
            <div className="mb-12">
              <div className="flex items-center space-x-3 mb-4">
                <span className="bg-slate-900 text-white px-3 py-1 rounded text-xs font-bold">{restaurant.genre}</span>
                <span className="text-slate-500 text-sm font-bold">{restaurant.region} / {restaurant.area}</span>
              </div>
              <h1 className="text-4xl font-serif font-bold text-slate-900 mb-6">{restaurant.name}</h1>
              <p className="text-lg text-slate-600 leading-relaxed mb-8">{restaurant.description}</p>

              {/* Business Stats Overlay */}
              <div className="grid grid-cols-2 md:grid-cols-4 gap-6 bg-white p-8 rounded-3xl border border-slate-100 shadow-xl mb-12">
                <div className="space-y-2">
                  <RatingStars label="料理の味" val={restaurant.tasteRating} />
                  <RatingStars label="接客の質" val={restaurant.serviceQuality} />
                </div>
                <div className="space-y-2">
                  <RatingStars label="静かさ" val={restaurant.quietness} />
                  <RatingStars label="総合評価" val={restaurant.avgRating} />
                </div>
                <div className="flex flex-col justify-center border-l border-slate-50 pl-6">
                  <span className="text-xs font-bold text-slate-400 uppercase mb-1">完全個室</span>
                  <span className="text-slate-900 font-bold">{restaurant.hasPrivateRoom ? 'あり' : 'なし'}</span>
                </div>
                <div className="flex flex-col justify-center border-l border-slate-50 pl-6">
                  <span className="text-xs font-bold text-slate-400 uppercase mb-1">コース対応</span>
                  <span className="text-slate-900 font-bold">{restaurant.hasCourse ? 'あり' : 'なし'}</span>
                </div>
              </div>

              {/* AI Analysis Section */}
              <div className="bg-slate-900 rounded-3xl p-8 text-white mb-16 shadow-2xl relative overflow-hidden">
                <div className="absolute top-0 right-0 p-8 opacity-10"><i className="fas fa-brain text-8xl"></i></div>
                <div className="relative z-10">
                  <div className="flex items-center mb-6">
                    <i className="fas fa-sparkles text-yellow-400 mr-2"></i>
                    <h3 className="text-xl font-bold">AI接待適性診断</h3>
                  </div>
                  {!analysis ? (
                    <button onClick={handleRunAnalysis} disabled={isAnalyzing} className="bg-white text-slate-900 px-8 py-3 rounded-full font-bold hover:bg-slate-100 transition-all flex items-center">
                      {isAnalyzing ? <><i className="fas fa-spinner fa-spin mr-2"></i> 分析中...</> : <><i className="fas fa-magic mr-2 text-indigo-500"></i> AI分析を実行</>}
                    </button>
                  ) : (
                    <div className="animate-in fade-in duration-500">
