            <form onSubmit={handleSubmitReview} className="p-12 overflow-y-auto space-y-12">
              <div className="grid grid-cols-1 md:grid-cols-2 gap-12">
                <div className="space-y-8">
                  <h4 className="text-[10px] font-bold text-slate-400 uppercase tracking-widest border-b border-slate-100 pb-2">レーティング</h4>
                  {[
                    { label: '総合満足度', key: 'rating' },
                    { label: '料理の味', key: 'tasteRating' },
                    { label: '接客の洗練さ', key: 'serviceQuality' },
                    { label: '店内の静かさ', key: 'quietness' },
                  ].map(r => (
                    <div key={r.key} className="flex items-center justify-between">
                      <span className="text-sm font-bold text-slate-700">{r.label}</span>
                      <div className="flex space-x-1.5">
                        {[1, 2, 3, 4, 5].map(s => (
                          <button key={s} type="button" onClick={() => setForm({ ...form, [r.key]: s })} className={`text-xl transition-colors ${(form as any)[r.key] >= s ? 'text-yellow-400' : 'text-slate-100'}`}><i className="fas fa-star"></i></button>
                        ))}
                      </div>
                    </div>
                  ))}
                </div>
                <div className="space-y-8">
                  <h4 className="text-[10px] font-bold text-slate-400 uppercase tracking-widest border-b border-slate-100 pb-2">利用状況</h4>
                  <div className="space-y-4">
                    <label className="block text-[10px] font-bold text-slate-500 uppercase">支払金額 (1人あたり)</label>
                    <input type="text" value={form.priceSpent} onChange={e => setForm({ ...form, priceSpent: e.target.value })} className="w-full bg-slate-50 border border-slate-100 rounded-xl px-5 py-4 text-sm focus:ring-2 focus:ring-slate-900 outline-none" placeholder="¥25,000" required />
                  </div>
                  <div className="space-y-4">
                    <label className="block text-[10px] font-bold text-slate-500 uppercase">個室形式</label>
                    <div className="flex flex-wrap gap-2">
                      {['完全個室', '半個室', 'なし'].map(t => (
                        <button key={t} type="button" onClick={() => setForm({ ...form, privateRoomType: t as PrivateRoomType })} className={`px-4 py-2 rounded-lg text-xs font-bold border transition-all ${form.privateRoomType === t ? 'bg-slate-900 text-white border-slate-900' : 'bg-white text-slate-400 border-slate-100 hover:border-slate-300'}`}>{t}</button>
                      ))}
                    </div>
                  </div>
                </div>
              </div>

              <div className="space-y-8">
                <h4 className="text-[10px] font-bold text-slate-400 uppercase tracking-widest border-b border-slate-100 pb-2">具体的な内容</h4>
                <div className="space-y-6">
                  <div>
                    <label className="block text-[10px] font-bold text-slate-500 uppercase mb-3">個室の評価 (機密性、広さ等)</label>
                    <input type="text" value={form.privateRoomDetail} onChange={e => setForm({ ...form, privateRoomDetail: e.target.value })} className="w-full bg-slate-50 border border-slate-100 rounded-xl px-5 py-4 text-sm focus:ring-2 focus:ring-slate-900 outline-none" placeholder="例: 隣の席の声が全く聞こえず、重要機密を伴う会談に最適だった。" />
                  </div>
                  <div>
                    <label className="block text-[10px] font-bold text-slate-500 uppercase mb-3">自由コメント</label>
                    <textarea rows={5} value={form.comment} onChange={e => setForm({ ...form, comment: e.target.value })} className="w-full bg-slate-50 border border-slate-100 rounded-[32px] px-6 py-6 text-sm focus:ring-2 focus:ring-slate-900 outline-none resize-none" placeholder="接客の間隔や、タクシーの手配のスムーズさ、ビジネスマンへの配慮など" required />
                  </div>
                </div>
              </div>

              <div className="pt-8 flex space-x-6">
                <button type="button" onClick={() => setShowReviewForm(false)} className="flex-1 py-5 border border-slate-100 rounded-2xl font-bold text-slate-400 hover:bg-slate-50 transition-all">キャンセル</button>
                <button type="submit" className="flex-1 py-5 bg-slate-900 text-white rounded-2xl font-bold hover:bg-slate-800 transition-all shadow-2xl shadow-slate-200">口コミを公開する</button>
              </div>
            </form>
          </div>
        </div>
      )}
    </div>
  );
};

export default Detail;

import React, { useState } from 'react';
import { mockRestaurants } from '../data/mockData';
import { Area, Region, Genre } from '../types';

interface SearchProps {
  onNavigate: (path: string, params?: any) => void;
  initialArea?: Area;
}

const Search: React.FC<SearchProps> = ({ onNavigate, initialArea }) => {
  const [selectedRegion, setSelectedRegion] = useState<Region | 'すべて'>('すべて');
  const [selectedArea, setSelectedArea] = useState<Area | 'すべて'>(initialArea || 'すべて');
  const [selectedGenre, setSelectedGenre] = useState<Genre | 'すべて'>('すべて');

  const regions: (Region | 'すべて')[] = ['すべて', '関東', '関西', '九州', '中部', '北海道・東北', '中国・四国'];
  const areasByRegion: Record<Region, Area[]> = {
    '関東': ['東京', '横浜'],
    '関西': ['大阪', '京都'],
    '九州': ['福岡'],
    '中部': ['名古屋'],
    '北海道・東北': ['札幌', '仙台'],
    '中国・四国': ['広島']
  };

  const genres: (Genre | 'すべて')[] = ['すべて', '日本料理', '寿司', 'イタリアン', 'フレンチ', '中華', '焼肉', 'ステーキ', '居酒屋'];

  const filteredRestaurants = mockRestaurants.filter(res => {
    if (selectedRegion !== 'すべて' && res.region !== selectedRegion) return false;
    if (selectedArea !== 'すべて' && res.area !== selectedArea) return false;
    if (selectedGenre !== 'すべて' && res.genre !== selectedGenre) return false;
    return true;
  });

  return (
    <div className="max-w-7xl mx-auto px-4 sm:px-6 lg:px-8 py-12">
      <div className="flex flex-col lg:flex-row gap-8">
        {/* Filter Sidebar */}
        <aside className="w-full lg:w-72 space-y-8">
          <div className="bg-white p-6 rounded-2xl shadow-sm border border-slate-200">
            <h3 className="text-lg font-bold text-slate-900 mb-6 flex items-center">
              <i className="fas fa-filter mr-2 text-slate-400"></i> 検索条件
            </h3>

            {/* Region Filter */}
            <div className="mb-6">
              <label className="text-xs font-bold text-slate-400 uppercase tracking-widest mb-3 block">地方</label>
              <select 
                value={selectedRegion}
                onChange={(e) => {
                  setSelectedRegion(e.target.value as any);
                  setSelectedArea('すべて');
                }}
                className="w-full bg-slate-50 border border-slate-200 rounded-xl px-4 py-3 text-sm focus:outline-none focus:ring-2 focus:ring-slate-900"
              >
                {regions.map(r => <option key={r} value={r}>{r}</option>)}
              </select>
            </div>

            {/* Area Filter */}
            {selectedRegion !== 'すべて' && (
              <div className="mb-6 animate-in slide-in-from-top-2">
                <label className="text-xs font-bold text-slate-400 uppercase tracking-widest mb-3 block">主要エリア</label>
                <div className="space-y-2">
                  <button
                    onClick={() => setSelectedArea('すべて')}
                    className={`block w-full text-left px-4 py-2 rounded-lg text-sm ${selectedArea === 'すべて' ? 'bg-slate-900 text-white' : 'hover:bg-slate-100 text-slate-600'}`}
                  >
                    すべて
                  </button>
                  {areasByRegion[selectedRegion as Region].map(a => (
                    <button
                      key={a}
                      onClick={() => setSelectedArea(a)}
                      className={`block w-full text-left px-4 py-2 rounded-lg text-sm ${selectedArea === a ? 'bg-slate-900 text-white font-bold' : 'hover:bg-slate-100 text-slate-600'}`}
                    >
                      {a}
                    </button>
                  ))}
                </div>
              </div>
            )}

            {/* Genre Filter */}
            <div>
              <label className="text-xs font-bold text-slate-400 uppercase tracking-widest mb-3 block">ジャンル</label>
              <select 
                value={selectedGenre}
                onChange={(e) => setSelectedGenre(e.target.value as any)}
                className="w-full bg-slate-50 border border-slate-200 rounded-xl px-4 py-3 text-sm focus:outline-none focus:ring-2 focus:ring-slate-900"
              >
                {genres.map(g => <option key={g} value={g}>{g}</option>)}
              </select>
            </div>
          </div>
        </aside>

        {/* Results */}
        <main className="flex-grow">
          <h2 className="text-2xl font-bold text-slate-900 mb-8">
            {selectedArea === 'すべて' ? (selectedRegion === 'すべて' ? '全国' : selectedRegion) : selectedArea}の飲食店
            <span className="ml-4 text-sm font-normal text-slate-400">{filteredRestaurants.length}件</span>
          </h2>

          <div className="space-y-6">
            {filteredRestaurants.map(res => (
              <div 
                key={res.id}
                onClick={() => onNavigate('detail', { id: res.id })}
                className="bg-white rounded-2xl overflow-hidden shadow-sm border border-slate-200 hover:shadow-md transition-all flex flex-col md:flex-row cursor-pointer group"
              >
                <div className="w-full md:w-80 h-64 md:h-auto overflow-hidden">
                  <img src={res.image} className="w-full h-full object-cover transition-transform duration-700 group-hover:scale-105" alt={res.name} />
                </div>
                <div className="p-8 flex-grow">
                  <div className="flex justify-between items-start mb-4">
                    <div>
                      <span className="text-xs font-bold text-slate-400 uppercase tracking-widest">{res.genre}</span>
                      <h3 className="text-2xl font-bold text-slate-900 mt-1">{res.name}</h3>
                    </div>
                    <div className="text-right">
                      <div className="flex items-center text-yellow-500 font-bold text-xl">
                        <i className="fas fa-star mr-1"></i> {res.avgRating}
                      </div>
                      <span className="text-xs text-slate-400">{res.reviewCount} 件</span>
                    </div>
                  </div>
                  <p className="text-slate-500 text-sm mb-6 line-clamp-2">{res.description}</p>
                  <div className="flex flex-wrap gap-x-6 gap-y-2 text-sm text-slate-600 border-t border-slate-50 pt-4">
                    <div className="flex items-center"><i className="fas fa-map-marker-alt w-5 text-slate-400"></i> {res.area}</div>
                    <div className="flex items-center"><i className="fas fa-yen-sign w-5 text-slate-400"></i> {res.priceRange}</div>
                    {/* Fix: use privateRoomType instead of the non-existent hasPrivateRoom property */}
                    <div className="flex items-center"><i className="fas fa-door-closed w-5 text-slate-400"></i> {res.privateRoomType !== 'なし' ? '個室あり' : '個室なし'}</div>
                  </div>
                </div>
              </div>
            ))}
          </div>
        </main>
      </div>
    </div>
  );
};

export default Search;
